BEGIN;
SELECT no_plan();
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT api.set_my_library_responsibility('11111111-1111-4111-8111-111111111111',true,'2026-09-13-v1');
SELECT set_config('test.upload',(SELECT upload_id::text FROM api.reserve_secure_upload('11111111-1111-4111-8111-111111111111','library_pdf','test.pdf','application/pdf',100)),true);
SELECT set_config('test.quarantine','b2222222-2222-4222-8222-222222222222/11111111-1111-4111-8111-111111111111/'||current_setting('test.upload')||'/source.pdf',true);
SELECT lives_ok(format('INSERT INTO storage.objects(bucket_id,name,metadata) VALUES(%L,%L,%L::jsonb)','upload-quarantine',current_setting('test.quarantine'),'{"size":100,"mimetype":"application/pdf"}'),'Reserved quarantine upload permitted');
SELECT throws_ok($$INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('educational-documents','b2222222-2222-4222-8222-222222222222/11111111-1111-4111-8111-111111111111/bypass.pdf','{"size":100,"mimetype":"application/pdf"}')$$,NULL,NULL,'Direct final upload denied');
SELECT is(api.confirm_secure_upload(current_setting('test.upload')::uuid),'uploaded','Owner confirms matching upload');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT is((SELECT count(*) FROM api.claim_secure_upload_for_service(current_setting('test.upload')::uuid)),1::bigint,'Worker claims upload once');
INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('educational-documents','b2222222-2222-4222-8222-222222222222/11111111-1111-4111-8111-111111111111/test.pdf','{"size":100,"mimetype":"application/pdf"}');
SELECT api.finish_secure_upload_for_service(current_setting('test.upload')::uuid,true,'b2222222-2222-4222-8222-222222222222/11111111-1111-4111-8111-111111111111/test.pdf',NULL,'clamav','test');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT set_config('test.document',api.save_library_content(NULL,'11111111-1111-4111-8111-111111111111','document','PDF prueba','Guías','published','{"path":"b2222222-2222-4222-8222-222222222222/11111111-1111-4111-8111-111111111111/test.pdf"}')::text,true);
SELECT set_config('request.jwt.claims','{"sub":"d1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM storage.objects WHERE bucket_id='educational-documents' AND name LIKE '%/test.pdf'),1::bigint,'Assigned patient can retrieve published PDF');
SELECT set_config('request.jwt.claims','{"sub":"d3333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM storage.objects WHERE bucket_id='educational-documents' AND name LIKE '%/test.pdf'),0::bigint,'Other patient cannot retrieve PDF');
SELECT set_config('request.jwt.claims','{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT api.save_library_content(id,organization_id,kind,title,category,'retired',body,updated_at) FROM api.content_library WHERE id=current_setting('test.document')::uuid;
SELECT set_config('request.jwt.claims','{"sub":"d1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM storage.objects WHERE bucket_id='educational-documents' AND name LIKE '%/test.pdf'),0::bigint,'Withdrawal revokes PDF retrieval');
RESET ROLE;
SELECT is((SELECT public FROM storage.buckets WHERE id='educational-documents'),false,'Bucket is private');
SELECT is((SELECT public FROM storage.buckets WHERE id='upload-quarantine'),false,'Quarantine bucket is private');
SELECT * FROM finish();
ROLLBACK;
